// Collect the keywords of column "keyword" into one list (one Actor run for the whole sheet).
const keywords = $input.all()
  .map((item) => String(item.json.keyword ?? '').trim())
  .filter(Boolean);
if (keywords.length === 0) throw new Error('No keyword found: add a column named "keyword" to the Keywords tab.');
return [{ json: { keywords } }];

// One row per keyword; the 12-month history becomes a compact text cell.
return $input.all().map(({ json: k }) => ({
  json: {
    keyword: k.keyword,
    found: k.found,
    searchVolume: k.searchVolume ?? null,
    cpcUsd: k.cpcUsd ?? null,
    competition: k.competitionLevel ?? null,
    keywordDifficulty: k.keywordDifficulty ?? null,
    searchIntent: k.searchIntent ?? null,
    trendYearlyPct: k.trendYearlyPct ?? null,
    last12Months: (k.monthlySearches || []).map((m) => `${m.month}: ${m.searchVolume}`).join(' | '),
    country: k.country,
    checkedAt: k.observedAt,
  },
}));
